#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int MAXN = 15;
const int MAXT = 65;
int N, T;
string grid[MAXN], sinkGrid[MAXN];
int cost[MAXN][MAXN];
int tab[MAXN][MAXN][MAXT];
int startY, startX;
const int dirY[4] = {1, -1, 0, 0};
const int dirX[4] = {0, 0, 1, -1};

struct DinicFlow {
    struct Edge {
        int to, cap, rev;
    };
    vector<vector<Edge>> con;
    vector<int> depth, ptr;
    int s, t;
    DinicFlow(int n, int ss, int tt) : con(n), depth(n), ptr(n), s(ss), t(tt) {}
    void connect(int a, int b, int c) {
        Edge f{b, c, (int)con[b].size()};
        Edge r{a, 0, (int)con[a].size()};
        con[a].push_back(f);
        con[b].push_back(r);
    }
    bool layered() {
        fill(depth.begin(), depth.end(), -1);
        depth[s] = 0;
        queue<int> q;
        q.push(s);
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (int i = 0; i < (int)con[v].size(); ++i) {
                Edge &e = con[v][i];
                if (depth[e.to] == -1 && e.cap > 0) {
                    depth[e.to] = depth[v] + 1;
                    q.push(e.to);
                }
            }
        }
        return depth[t] != -1;
    }
    int send(int v, int flow) {
        if (v == t) return flow;
        for (int &i = ptr[v]; i < (int)con[v].size(); ++i) {
            Edge &e = con[v][i];
            if (depth[e.to] == depth[v] + 1 && e.cap > 0) {
                int got = send(e.to, min(flow, e.cap));
                if (got) {
                    e.cap -= got;
                    con[e.to][e.rev].cap += got;
                    return got;
                }
            }
        }
        return 0;
    }
    ll run() {
        ll ans = 0;
        while (layered()) {
            fill(ptr.begin(), ptr.end(), 0);
            while (int f = send(s, 2e9)) ans += f;
        }
        return ans;
    }
};

void computeDist() {
    queue<int> q;
    q.push(startY * N + startX);
    cost[startY][startX] = 1;
    int depth = 1;
    while (!q.empty()) {
        int sz = (int)q.size();
        for (int it = 0; it < sz; ++it) {
            int pos = q.front(); q.pop();
            int y = pos / N;
            int x = pos % N;
            for (int d = 0; d < 4; ++d) {
                int ny = y + dirY[d];
                int nx = x + dirX[d];
                if (ny < 0 || ny >= N || nx < 0 || nx >= N) continue;
                if (cost[ny][nx] || grid[ny][nx] == 'Y') continue;
                cost[ny][nx] = depth;
                q.push(ny * N + nx);
            }
        }
        ++depth;
        if (depth > T) depth = T;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> N >> T;
    for (int i = 0; i < N; ++i) {
        cin >> grid[i];
        for (int j = 0; j < N; ++j)
            if (grid[i][j] == 'Z') startY = i, startX = j;
    }
    getline(cin, grid[N]);
    getline(cin, grid[N]);
    for (int i = 0; i < N; ++i) cin >> sinkGrid[i];
    computeDist();
    int vertices = 0;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (grid[i][j] >= '0' && grid[i][j] <= '9') {
                if (cost[i][j] == 0) cost[i][j] = T;
                for (int k = 0; k < cost[i][j]; ++k)
                    tab[i][j][k] = ++vertices;
            }
            if (sinkGrid[i][j] >= '1' && sinkGrid[i][j] <= '9')
                tab[i][j][cost[i][j]] = ++vertices;
        }
    }
    const int INF = 1000000000;
    int S = 0, E = vertices + 3;
    DinicFlow mf(vertices + 5, S, E);
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (grid[i][j] >= '1' && grid[i][j] <= '9')
                mf.connect(S, tab[i][j][0], grid[i][j] - '0');
            for (int d = 0; d < 4; ++d) {
                int ny = i + dirY[d];
                int nx = j + dirX[d];
                if (ny < 0 || ny >= N || nx < 0 || nx >= N) continue;
                if (grid[ny][nx] == 'Y' || grid[ny][nx] == 'Z') continue;
                for (int k = 0;; ++k) {
                    if (tab[i][j][k] == 0) break;
                    if (k == cost[i][j] && sinkGrid[i][j] >= '1' && sinkGrid[i][j] <= '9') break;
                    if (tab[ny][nx][k + 1])
                        mf.connect(tab[i][j][k], tab[ny][nx][k + 1], INF);
                }
            }
            if (sinkGrid[i][j] >= '1' && sinkGrid[i][j] <= '9') {
                for (int k = 0; k < cost[i][j]; ++k)
                    mf.connect(tab[i][j][k], tab[i][j][k + 1], INF);
                mf.connect(tab[i][j][cost[i][j]], E, sinkGrid[i][j] - '0');
            }
        }
    }
    cout << mf.run() << '\n';
}
