import java.util.*;

public class Main {
    static final int MAXN = 15;
    static final int MAXT = 65;
    static int N, T;
    static String[] grid = new String[MAXN];
    static String[] sinkGrid = new String[MAXN];
    static int[][] cost = new int[MAXN][MAXN];
    static int[][][] tab = new int[MAXN][MAXN][MAXT];
    static int startY, startX;
    static final int[] dirY = {1, -1, 0, 0};
    static final int[] dirX = {0, 0, 1, -1};

    static class DinicFlow {
        static class Edge {
            int to, cap, rev;
            Edge(int to, int cap, int rev) {
                this.to = to;
                this.cap = cap;
                this.rev = rev;
            }
        }
        ArrayList<ArrayList<Edge>> con;
        int[] depth, ptr;
        int s, t;

        DinicFlow(int n, int ss, int tt) {
            con = new ArrayList<>(n);
            for (int i = 0; i < n; i++) con.add(new ArrayList<>());
            depth = new int[n];
            ptr = new int[n];
            s = ss;
            t = tt;
        }

        void connect(int a, int b, int c) {
            Edge f = new Edge(b, c, con.get(b).size());
            Edge r = new Edge(a, 0, con.get(a).size());
            con.get(a).add(f);
            con.get(b).add(r);
        }

        boolean layered() {
            Arrays.fill(depth, -1);
            depth[s] = 0;
            Queue<Integer> q = new LinkedList<>();
            q.add(s);
            while (!q.isEmpty()) {
                int v = q.poll();
                for (Edge e : con.get(v)) {
                    if (depth[e.to] == -1 && e.cap > 0) {
                        depth[e.to] = depth[v] + 1;
                        q.add(e.to);
                    }
                }
            }
            return depth[t] != -1;
        }

        int send(int v, int flow) {
            if (v == t) return flow;
            for (; ptr[v] < con.get(v).size(); ptr[v]++) {
                Edge e = con.get(v).get(ptr[v]);
                if (depth[e.to] == depth[v] + 1 && e.cap > 0) {
                    int got = send(e.to, Math.min(flow, e.cap));
                    if (got > 0) {
                        e.cap -= got;
                        con.get(e.to).get(e.rev).cap += got;
                        return got;
                    }
                }
            }
            return 0;
        }

        long run() {
            long ans = 0;
            while (layered()) {
                Arrays.fill(ptr, 0);
                int f;
                while ((f = send(s, 2000000000)) > 0) ans += f;
            }
            return ans;
        }
    }

    static void computeDist() {
        Queue<Integer> q = new LinkedList<>();
        q.add(startY * N + startX);
        cost[startY][startX] = 1;
        int depth = 1;
        while (!q.isEmpty()) {
            int sz = q.size();
            for (int it = 0; it < sz; it++) {
                int pos = q.poll();
                int y = pos / N;
                int x = pos % N;
                for (int d = 0; d < 4; d++) {
                    int ny = y + dirY[d];
                    int nx = x + dirX[d];
                    if (ny < 0 || ny >= N || nx < 0 || nx >= N) continue;
                    if (cost[ny][nx] != 0 || grid[ny].charAt(nx) == 'Y') continue;
                    cost[ny][nx] = depth;
                    q.add(ny * N + nx);
                }
            }
            depth++;
            if (depth > T) depth = T;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextInt();
        T = sc.nextInt();
        sc.nextLine(); // consume newline
        for (int i = 0; i < N; i++) {
            grid[i] = sc.next();
            for (int j = 0; j < N; j++)
                if (grid[i].charAt(j) == 'Z') {
                    startY = i; startX = j;
                }
        }
        sc.nextLine(); // consume the newline after last grid token
        sc.nextLine(); // extra line (as in original C++ code)
        for (int i = 0; i < N; i++) sinkGrid[i] = sc.next();
        computeDist();

        int vertices = 0;
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (grid[i].charAt(j) >= '0' && grid[i].charAt(j) <= '9') {
                    if (cost[i][j] == 0) cost[i][j] = T;
                    for (int k = 0; k < cost[i][j]; k++)
                        tab[i][j][k] = ++vertices;
                }
                if (sinkGrid[i].charAt(j) >= '1' && sinkGrid[i].charAt(j) <= '9')
                    tab[i][j][cost[i][j]] = ++vertices;
            }
        }
        final int INF = 1000000000;
        int S = 0, E = vertices + 3;
        DinicFlow mf = new DinicFlow(vertices + 5, S, E);
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (grid[i].charAt(j) >= '1' && grid[i].charAt(j) <= '9')
                    mf.connect(S, tab[i][j][0], grid[i].charAt(j) - '0');
                for (int d = 0; d < 4; d++) {
                    int ny = i + dirY[d];
                    int nx = j + dirX[d];
                    if (ny < 0 || ny >= N || nx < 0 || nx >= N) continue;
                    if (grid[ny].charAt(nx) == 'Y' || grid[ny].charAt(nx) == 'Z') continue;
                    for (int k = 0; ; k++) {
                        if (tab[i][j][k] == 0) break;
                        if (k == cost[i][j] && sinkGrid[i].charAt(j) >= '1' && sinkGrid[i].charAt(j) <= '9') break;
                        if (tab[ny][nx][k + 1] != 0)
                            mf.connect(tab[i][j][k], tab[ny][nx][k + 1], INF);
                    }
                }
                if (sinkGrid[i].charAt(j) >= '1' && sinkGrid[i].charAt(j) <= '9') {
                    for (int k = 0; k < cost[i][j]; k++)
                        mf.connect(tab[i][j][k], tab[i][j][k + 1], INF);
                    mf.connect(tab[i][j][cost[i][j]], E, sinkGrid[i].charAt(j) - '0');
                }
            }
        }
        System.out.println(mf.run());
        sc.close();
    }
}
